<?php
require __DIR__.'/common.php'; ensure_method(['POST']); require_user(); $d=json_input();$message=trim($d['message']??'');if($message==='')respond(['error'=>'Pesan kosong'],422);if(strlen($message)>8000)respond(['error'=>'Pesan terlalu panjang'],422);
$key=getenv('OPENAI_API_KEY');if(!$key)respond(['error'=>'OPENAI_API_KEY belum dikonfigurasi di hosting'],503);
$history=is_array($d['history']??null)?array_slice($d['history'],-12):[];$messages=[['role'=>'system','content'=>'Kamu adalah Izanami AI. Jawab dalam Bahasa Indonesia secara natural, ringkas, dan jujur.']];foreach($history as $h){if(!isset($h['text'])||!is_string($h['text']))continue;$messages[]=['role'=>($h['role']??'')==='ai'?'assistant':'user','content'=>substr($h['text'],0,4000)];}$messages[]=['role'=>'user','content'=>$message];
$ch=curl_init('https://api.openai.com/v1/chat/completions');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_TIMEOUT=>35,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.$key],CURLOPT_POSTFIELDS=>json_encode(['model'=>'gpt-4o-mini','messages'=>$messages,'temperature'=>0.7,'max_tokens'=>800])]);$raw=curl_exec($ch);$http=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$out=json_decode($raw?:'',true);if($http!==200)respond(['error'=>'Layanan AI gagal merespons. Periksa API key dan kuota.'],502);$reply=trim($out['choices'][0]['message']['content']??'');$s=$pdo->prepare('INSERT INTO chat_messages(user_id,role,message) VALUES(?,?,?)');$s->execute([$_SESSION['user_id'],'user',$message]);$s->execute([$_SESSION['user_id'],'assistant',$reply]);respond(['reply'=>$reply]);
